    }                                                                       

    transition!{                                                            
        end(label: Label<DT>, rid: ReqId, output: OutputOperation<DT>) {    
            require label == AsyncLabel::<DT>::End(rid, output);            
            require pre.resps.dom().contains(rid);                          
